files.001.sql:
CREATE TABLE stock(sku TEXT PRIMARY KEY, quantity INTEGER NOT NULL);
INSERT INTO stock VALUES ('A',10),('C',0);
CREATE VIEW legacy_stock AS SELECT sku, quantity AS units FROM stock;

files.002.sql:
ALTER TABLE stock ADD COLUMN reserved INTEGER NOT NULL DEFAULT 0;
DROP VIEW legacy_stock;
CREATE VIEW legacy_stock AS SELECT sku, quantity-reserved AS units FROM stock;

